internal object ParamSfo {
    fun string(sfo: File, key: String): String? =
        runCatching { string(sfo.readBytes(), key) }.getOrNull()

    fun int(sfo: File, key: String): Int? =
        runCatching { int(sfo.readBytes(), key) }.getOrNull()

    fun string(bytes: ByteArray, key: String): String? {
        val entry = entry(bytes, key) ?: return null
        // Values are UTF-8 and padded with NULs to their declared maximum length.
        return String(bytes, entry.offset, entry.length, Charsets.UTF_8).trimEnd('\u0000', ' ')
    }

    /**
     * A PARAM.SFO integer (BOOTABLE, VERSION, ...), stored as a little-endian int32.
     *
     * Added beside [string] rather than as a second parser because the 16-byte index
     * entry layout -- two u16 offsets, a u16 format, a u32 length and a u32 data offset
     * -- is the part that is easy to get subtly wrong, and the scanner now has to read
     * both a string and an integer out of the same file to decide what a folder is.
     */
    fun int(bytes: ByteArray, key: String): Int? {
        val entry = entry(bytes, key) ?: return null
        if (entry.length < 4) return null
        return java.nio.ByteBuffer.wrap(bytes, entry.offset, 4)
            .order(java.nio.ByteOrder.LITTLE_ENDIAN).int
    }

    private class Entry(val offset: Int, val length: Int)

    /**
     * The byte range a key's value occupies, or null when the file is not a PARAM.SFO
     * or has no such key.
     *
     * Every failure answers null rather than throwing, for the reason documented on
     * the object: a truncated or hand-edited SFO must never take a caller down, because
     * the callers use the answer to decide whether to LIST a game.
     */
    private fun entry(bytes: ByteArray, key: String): Entry? {
        val buffer = java.nio.ByteBuffer.wrap(bytes).order(java.nio.ByteOrder.LITTLE_ENDIAN)
        // "\0PSF", then key-table start, data-table start, entry count.
        if (bytes.size < 20 || buffer.getInt(0) != 0x46535000) return null
        val keyTable = buffer.getInt(8)
        val dataTable = buffer.getInt(12)
        for (index in 0 until buffer.getInt(16)) {
            val entry = 20 + index * 16
            if (entry + 16 > bytes.size) break
            val keyStart = keyTable + (buffer.getShort(entry).toInt() and 0xFFFF)
            if (keyStart < 0 || keyStart >= bytes.size) break
            var keyEnd = keyStart
            while (keyEnd < bytes.size && bytes[keyEnd] != 0.toByte()) keyEnd++
            if (String(bytes, keyStart, keyEnd - keyStart) != key) continue
            val dataStart = dataTable + buffer.getInt(entry + 12)
            val dataLength = buffer.getInt(entry + 4)
            if (dataStart < 0 || dataLength < 0 || dataStart + dataLength > bytes.size) break
            return Entry(dataStart, dataLength)
        }
        return null
    }
}

/**
 * True when this directory IS a game rather than a folder containing games.
 *
 * Two shapes, both common and neither an .iso:
 *   - a JB folder dump, which keeps the disc layout: <dir>/PS3_GAME/PARAM.SFO
 *     (PS3_DISC.SFB alongside it on a real disc rip)
 *   - an installed/HDD game folder -- PARAM.SFO next to USRDIR. This is what
 *     RPCS3's own games directory holds, and the shape prototypes that never
 *     got a retail master ship in.
 *
 * Having the shape is NOT enough to be listed. A folder qualifies only if the
 * emulator can actually boot it -- see [isBootableTitle] -- which is what keeps
 * the library free of the folders that merely LOOK like titles.
 *
 * Case-insensitive: these come off FAT/exFAT cards and out of archives, so
 * "PS3_GAME" is as likely to be "ps3_game".
 */
private fun isPs3GameFolder(directory: File): Boolean {
    val discSfo = child(directory, "PS3_GAME", "PARAM.SFO")?.takeIf { it.isFile }
    val topSfo = child(directory, "PARAM.SFO")?.takeIf { it.isFile }
    val sfo = discSfo ?: topSfo

    // No SFO anywhere: only a bare disc-rip marker can still make this a game.
    if (sfo == null) return child(directory, "PS3_DISC.SFB")?.isFile == true

    // A JB dump keeps its payload under PS3_GAME/USRDIR; an installed game has
    // USRDIR next to its own SFO. A SFO with no payload beside or under it is a
    // title's metadata that got copied out of context, not a game.
    if (discSfo == null && child(directory, "USRDIR")?.isDirectory != true) return false

    // A game data install has this exact shape too, a PARAM.SFO next to USRDIR, so the
    // layout alone cannot tell it apart from an HDD game. It holds no EBOOT, so listing it
    // gave every title that installs data a second tile that cannot boot (Skate 3's 1.1 GB
    // BLUS30464_INSTALL, sitting next to the disc it belongs to). CATEGORY is what
    // separates them: GD is data, HG and DG are games. The native scanner already rejects
    // these because fetchGameInfo requires BOOTABLE and game data does not set it. This
    // applies the same rule to the folder path, which never opened the SFO at all.
    if (sfoCategory(sfo) == "GD") return false

    return isBootableTitle(directory, sfo)
}

/**
 * True when the emulator can boot this folder, which is the bar for listing it.
 *
 * The folder tests above only asked whether a title's SHAPE was on disk. That accepts a
 * lot of folders which are not games the user can play, and every one of them is a tile
 * that fails on tap: _rpcsx_boot resolves a directory to its EBOOT (locateEbootPath) and,
 * finding none, hands the bare directory to Emu.BootGame, which answers
 * invalid_file_or_folder. So the two symptoms are the same bug -- junk in the list, and
 * "Game failed to start: InvalidFileOrFolder" on the entries that got there.
 *
 * A user's shared folder holds whole trees of this: the app's own emulator directory with
 * a dev_hdd0 full of homebrew (Cheat Engine's CEFramework / CEHtmlApi / CEHtmlUI / CEPhWeb
 * are four separate PS3 titles, not four games), the log directory, PS1 ROM sets, and every
 * other app's leftovers -- all sitting in the same folder as the real disc images.
 *
 * The bar is deliberately the same one the core already applies in fetchGameInfo
 * (rpcsx-android.cpp): BOOTABLE set, a TITLE_ID, and an EBOOT the core can open. Listing
 * less than the core can boot is the failure that costs the user the most time, because a
 * tile that cannot boot looks like a broken emulator rather than a folder that was never
 * a game.
 *
 * An SFO that cannot be read proves nothing, so a parse failure falls back to the old
 * structural answer instead of hiding a real game over a truncated PARAM.SFO.
 */
private fun isBootableTitle(directory: File, sfo: File): Boolean {
    if (!hasBootableEboot(directory)) {
        android.util.Log.i(
            ScanTag,
            "  '${directory.name}': not listed, no EBOOT.BIN/ISO.BIN.EDAT (tried ${EBOOT_PATHS.joinToString()})",
        )
        return false
    }
    val titleId = ParamSfo.string(sfo, "TITLE_ID")
    val bootable = ParamSfo.int(sfo, "BOOTABLE")
    // Unreadable SFO: keep the structural answer rather than hide a real game.
    if (titleId == null && bootable == null) {
        android.util.Log.w(
            ScanTag,
            "  '${directory.name}': PARAM.SFO unparseable, accepting on structure alone",
        )
        return true
    }
    if (titleId.isNullOrBlank()) {
        android.util.Log.i(ScanTag, "  '${directory.name}': not listed, PARAM.SFO has no TITLE_ID")
        return false
    }
    if (bootable == 0) {
        android.util.Log.i(
            ScanTag,
            "  '${directory.name}': not listed, PARAM.SFO BOOTABLE=0 (title $titleId)",
        )
        return false
    }
    return true
}

/**
 * The EBOOT the core would boot this folder through, in the order it looks for them.
 *
 * Must stay in step with locateEbootPath in android/src/rpcsx-android.cpp: a folder the
 * scanner accepts but the core cannot resolve is exactly the tile that fails to start.
 */
private fun hasBootableEboot(directory: File): Boolean =
    EBOOT_PATHS.any { path -> child(directory, *path)?.isFile == true }

/**
 * Case-insensitive path lookup inside a directory, or null when any segment is missing.
 *
 * One [File.listFiles] per segment rather than a constructed [File] probe, because these
 * names come off FAT/exFAT cards where the real casing is arbitrary.
 */
private fun child(directory: File, vararg path: String): File? {
    var current = directory
    for (segment in path) {
        current = runCatching { current.listFiles() }
            .getOrNull()
            ?.firstOrNull { it.name.equals(segment, ignoreCase = true) }
            ?: return null
    }
    return current
}

