/** [isPs3GameDocument] over a SAF tree. */
private fun isPs3GameDocument(directory: DocumentFile): Boolean {
    val children = runCatching { directory.listFiles() }.getOrNull() ?: return false
    fun find(name: String) = children.firstOrNull { it.name.equals(name, ignoreCase = true) }

    // The same bar as the raw scan, reduced to what a document tree can answer: an EBOOT the
    // core could actually open. BOOTABLE and TITLE_ID are not read here -- a SAF listing has no
    // path to open the SFO with, and the raw scan is the one that runs whenever all-files access
    // is granted, which the emulator needs at boot anyway.
    fun hasEboot(from: List<DocumentFile>, segments: List<String>): Boolean {
        val head = segments.first()
        val candidates = from.filter { it.name.equals(head, ignoreCase = true) }
        if (segments.size == 1) return candidates.any { it.isFile }
        return candidates.any { it.isDirectory } && candidates
            .filter { it.isDirectory }
            .any { hasEboot(runCatching { it.listFiles() }.getOrNull().orEmpty(), segments.drop(1)) }
    }
    fun hasEbootIn(children: List<DocumentFile>) = EBOOT_PATHS.any { hasEboot(children, it.split('/')) }

    if (find("PS3_DISC.SFB")?.isFile == true) return true
    val gameDir = find("PS3_GAME")?.takeIf { it.isDirectory }
    if (gameDir != null) {
        val inner = runCatching { gameDir.listFiles() }.getOrNull().orEmpty()
        if (inner.any { it.isFile && it.name.equals("PARAM.SFO", ignoreCase = true) } &&
            (hasEbootIn(inner) || hasEbootIn(children))
        ) return true
    }
    return find("PARAM.SFO")?.isFile == true &&
        find("USRDIR")?.isDirectory == true &&
