import com.xeno.ParamSfo
import com.xeno.ScanLog
import com.xeno.Scanner
import java.io.File

/**
 * Writes a PARAM.SFO the way psf::write does, so the fixtures are parsed by the same code
 * path the device uses. Layout matches the reader: 20-byte header, then a 16-byte index
 * entry per key (key_table_offset u16, align u16, data_size u32, data_max_size u32,
 * data_table_offset u32), then the key table and the data table.
 */
private fun buildSfo(entries: List<Pair<String, ByteArray>>): ByteArray {
    val header = 20
    val indexSize = entries.size * 16
    val keyTable = header + indexSize
    val keyBytes = entries.sumOf { it.first.length + 1 }
    val dataTable = keyTable + keyBytes
    val dataBytes = entries.sumOf { it.second.size }

    val out = ByteArray(dataTable + dataBytes)
    fun putInt(off: Int, v: Int) {
        out[off] = (v and 0xFF).toByte()
        out[off + 1] = ((v shr 8) and 0xFF).toByte()
        out[off + 2] = ((v shr 16) and 0xFF).toByte()
        out[off + 3] = ((v shr 24) and 0xFF).toByte()
    }
    fun putShort(off: Int, v: Int) {
        out[off] = (v and 0xFF).toByte()
        out[off + 1] = ((v shr 8) and 0xFF).toByte()
    }
    fun putBytes(off: Int, v: ByteArray) {
        v.copyInto(out, off)
    }

    // "\0PSF", version 1, key table start, data table start, entry count.
    out[0] = 0; out[1] = 0x50; out[2] = 0x53; out[3] = 0x46
    putInt(4, 1)
    putInt(8, keyTable)
    putInt(12, dataTable)
    putInt(16, entries.size)

    var keyOffset = 0
    var dataOffset = 0
    entries.forEachIndexed { i, (key, value) ->
        val e = header + i * 16
        putShort(e, keyOffset)
        putShort(e + 2, 4)
        putInt(e + 4, value.size)
        putInt(e + 8, value.size)
        putInt(e + 12, dataOffset)
        putBytes(keyTable + keyOffset, key.toByteArray(Charsets.UTF_8) + byteArrayOf(0))
        putBytes(dataTable + dataOffset, value)
        keyOffset += key.length + 1
        dataOffset += value.size
    }
    return out
}

private fun sfoBytes(
    titleId: String? = "BLUS30464",
    bootable: Int? = 1,
    category: String? = "HG",
    title: String? = "Skate",
): ByteArray {
    val entries = mutableListOf<Pair<String, ByteArray>>()
    titleId?.let { entries += "TITLE_ID" to it.toByteArray() }
    bootable?.let { entries += "BOOTABLE" to ByteArray(4).also { b -> b[0] = it.toByte() } }
    category?.let { entries += "CATEGORY" to it.toByteArray() }
    title?.let { entries += "TITLE" to it.toByteArray() }
    return buildSfo(entries)
}

private var failures = 0
private var checks = 0

private fun check(name: String, actual: Boolean, expected: Boolean) {
    checks++
    if (actual != expected) {
        failures++
        println("FAIL  $name: expected listed=$expected, got $actual")
    } else {
        println("ok    $name: listed=$actual")
    }
}

private fun dir(name: String, under: File): File = File(under, name).apply { mkdirs() }

