private fun isPs3GameFolder(directory: File): Boolean {
    val sfo = child(directory, "PS3_GAME", "PARAM.SFO")?.takeIf { it.isFile }
        ?: child(directory, "PARAM.SFO")?.takeIf { it.isFile }

    // A disc rip whose SFO is missing or unreadable: the PS3_DISC.SFB marker is all that is
    // left to go on, so the EBOOT is the only thing here that can still be checked.
    if (sfo == null) {
        if (child(directory, "PS3_DISC.SFB")?.isFile != true) return false
        return hasBootableEboot(directory)
    }

    // A game data install has this exact shape too, a PARAM.SFO next to USRDIR, so the
    // layout alone cannot tell it apart from an HDD game. It holds no EBOOT, so listing it
    // gave every title that installs data a second tile that cannot boot (Skate 3's 1.1 GB
    // BLUS30464_INSTALL, sitting next to the disc it belongs to). CATEGORY is what
    // separates them: GD is data, HG and DG are games. The native scanner already rejects
    // these because fetchGameInfo requires BOOTABLE and game data does not set it. This
    // applies the same rule to the folder path, which never opened the SFO at all.
    if (sfoCategory(sfo) == "GD") return false

    // The payload check is left entirely to [hasBootableEboot], which mirrors the core.
    // Asking for USRDIR here as well used to be a second, stricter rule that hid games the
    // emulator boots perfectly well -- locateEbootPath also accepts an EBOOT.BIN sitting
    // beside the SFO -- so the two answers could disagree about the same folder.
    return isBootableTitle(directory, sfo)
}

