fun start() {
    synchronized(vmLifecycleLock) {
        if (vmStopInProgress || vmRunLoopActive || eState.value != EmuState.STOPPED) {
            vmRestartAfterStop = true
            return
        }
        vmRunLoopActive = true
    }

    invoke {
        var booted = false
        try {
            eState.value = EmuState.RUNNING
            println("@@ANDROID_START_VM@@ kind=game path=${com.xeno.CloudSync.redactUrl(m_szGamefile.take(240))}")

            // Push the curated settings before the VM reads them.
            //
            // applyTo() was only ever called from UI actions -- a settings screen, the
            // in-game overlay, the texture manager. Nothing pushed at LAUNCH, so
            // config.yml was authoritative at boot and, once it diverged from the store,
            // stayed diverged forever: nothing rewrites a node the user is not actively
            // changing.
            //
            // That is not theoretical. A stale "PPU Decoder: Interpreter (static)" sat in
            // config.yml while the settings screen and the store both read Recompiler
            // (LLVM), so every game ran interpreted -- black screen, OSD fine, one PPU
            // thread pegged, no PPU compile, and identical behaviour on a build with none
            // of our commits. A day went into bisecting code for it.
            //
            // Cheap: applyTo batches its ~165 keys, and this runs once per launch.
            try {
                com.xeno.config.ConfigStore
                    .resolveForGame(currentGame.value?.settingsKey)
                    .applyTo()
            } catch (t: Throwable) {
                android.util.Log.w("XENO", "launch: failed to apply settings", t)
            }
            // Local co-op: re-pair controllers each session (first pad = P1,
            // next = P2) so player slots are deterministic per boot.
            com.xeno.input.PadRouter.reset()
            WindowImpl.showLibrary.value = false
            WindowImpl.overlayVisible.value = false
            WindowImpl.toolbarVisible.value = false
            emulationOwnsOrientation = true
            // Opt-in only: blocks a controller's Home button from minimising the game,
            // which the app cannot do any other way — HOME never reaches us (#425).
            instance?.let { com.xeno.ui.ScreenPinning.start(it) }
            applyRendererPrefs()
            // Learn this title's real serial for next time.
            //
            // The library only gets a serial by regex over the filename, so a disc that
            // does not spell out its title id resolves per-game settings under its
            // filename while the core boots it as the serial and reads there. The core
            // reports the serial about a second into boot, which is too late for the
            // settings just pushed above -- but recording it now means every later boot
            // resolves under the right key. See ConfigStore.rememberSerial.
            runCatching {
                com.xeno.config.ConfigStore.rememberSerial(
                    currentGame.value?.settingsKey,
                    com.xeno.NativeApp.getGameSerial())
            }
            // Both of these are consumed by native when the VM boots, so they must be
            // pushed BEFORE runVMThread (which blocks until the VM exits). One resolve,
            // per-game ∘ global.
            val bootCfg = com.xeno.config.ConfigStore
                .resolveForGame(
                    com.xeno.config.ConfigStore.effectiveKey(currentGame.value?.settingsKey))
            // Read by VMManager::SetEmuThreadAffinities during boot.
            runCatching { NativeApp.setAffinityMode(bootCfg.affinityMode) }
            // The hold itself waits for the VM to come up. BIOS boots skip it.
            if (bootCfg.autoProgressiveScan)
                startAutoProgressiveScanHold()
            booted = NativeApp.runVMThread(m_szGamefile)
            // A failed boot used to be indistinguishable from an instant game exit:
            // runVMThread's result was dropped, so the app bounced back to the
            // library with no message and no log. Surface the BootResult the bridge
            // now keeps — DecryptionError in particular means "no licence for this
            // PKG game", which the user can actually fix.
            if (!booted) {
                val reason = com.xeno.Rpcs3Bridge.lastBootError ?: "unknown"
                println("@@ANDROID_BOOT_FAILED@@ reason=$reason path=${com.xeno.CloudSync.redactUrl(m_szGamefile.take(240))}")
                // The library normally intercepts a locked game before it ever boots
                // (HomeViewModel.launch), so reaching here means the lock state was
                // stale — a licence deleted outside the app, say. Point at the per-game
                // action that fixes it, which a rescan will also surface as a badge.
                val hint = if (reason == "DecryptionError")
                    " — it needs a .rap licence. Long-press the game and choose Install licence."
                else ""
                instance?.let { act ->
                    act.runOnUiThread {
                        android.widget.Toast.makeText(
                            act,
                            "Game failed to start: $reason$hint",
                            android.widget.Toast.LENGTH_LONG,
                        ).show()
                    }
                }
            }
        } finally {
            // runVMThread blocks until the VM exits (Stopping/Shutdown
            // observed). Drop back to STOPPED only after native has
            // actually unwound, so users can't launch the next game
            // while the previous VM is still tearing down.
            eState.value = EmuState.STOPPED
            // Cloud saves: a game just exited and its save data is
            // fresh — push it before anything else can overwrite the
            // memory card. Fire-and-forget: this runs on the run-loop
            // thread and the app stays alive afterwards, so the upload
            // has real time and must not block the launch of the next
            // title. Idempotent (PUT overwrite), so the shutdown push
            // in onDestroy is a harmless duplicate.
            val syncSnapshot = com.xeno.CloudSync.snapshot()
            if (booted && syncSnapshot.autoPush && syncSnapshot.config != null) {
                kotlin.concurrent.thread(name = "cloud-sync-exit") {
                    runCatching {
                        val pushed = kotlinx.coroutines.runBlocking { com.xeno.CloudSync.pushAllSaves() }
                        android.util.Log.i("CloudSync", "game-exit sync pushed $pushed save(s)")
                    }
                }
            }
            // GitHub transport is independent of the WebDAV one — run it as its own
            // worker if configured, so a game exit syncs to whichever cloud is set up.
            val gdriveSnapshot = com.xeno.GoogleDriveSync.snapshot()
            if (booted && gdriveSnapshot.autoPush && gdriveSnapshot.config != null) {
                kotlin.concurrent.thread(name = "gdrive-sync-exit") {
                    runCatching {
                        val pushed = kotlinx.coroutines.runBlocking { com.xeno.GoogleDriveSync.pushAllSaves() }
                        android.util.Log.i("GoogleDriveSync", "game-exit sync pushed $pushed save(s)")
                    }
                }
            }

            // GitHub transport is independent of the WebDAV one — run it as its own
            // worker if configured, so a game exit syncs to whichever cloud is set up.
            val ghSnapshot = com.xeno.GithubSaveSync.snapshot()
            if (booted && ghSnapshot.autoPush && ghSnapshot.token != null) {
                kotlin.concurrent.thread(name = "github-sync-exit") {
                    runCatching {
                        val pushed = kotlinx.coroutines.runBlocking { com.xeno.GithubSaveSync.pushAll() }
                        android.util.Log.i("GithubSaveSync", "game-exit sync pushed $pushed save(s)")
                    }
                }
            }
            val restartNow = synchronized(vmLifecycleLock) {
                vmRunLoopActive = false
                vmStopInProgress = false
                if (vmRestartAfterStop) {
                    vmRestartAfterStop = false
                    true
                } else {
                    false
                }
            }
            if (restartNow) {
                // Queued on vmStopControl rather than called here, because "the run loop has
                // exited" is NOT "the stop has finished". stop() enqueues NativeApp.shutdown()
                // on that same single-thread executor, and shutdown() sets stopRequested and
                // calls kill(). This finally block runs as soon as boot() returns -- which
                // stopRequested is exactly what causes -- so calling start() straight from
                // here raced ahead of the shutdown that released it, and the kill then landed
                // on the VM that had just started, killing it too. Traced on a Restart press:
                // START_VM 6ms after the stop began, then a SECOND START_VM 15s later once
                // the freshly-killed VM unwound, which is the "Restart kicks you back to the
                // library" report.
                //
                // vmStopControl is single-threaded, so this cannot begin until the pending
                // shutdown has returned. execute() and not submit().get(): waiting here would
                // block the run-loop thread that kill() may itself be waiting on.
                vmStopControl.execute { start() }
            } else {
                WindowImpl.toolbarVisible.value = true
                WindowImpl.showLibrary.value = false
                WindowImpl.overlayVisible.value = false
                // This is the branch that actually fires on a normal game exit (stop()'s
                // equivalent block loses the vmRunLoopActive race), so the return-to-library
                // cleanup has to happen here or the launcher keeps the game's rotation.
                onReturnedToLibrary()
                finishToLauncherIfRequested()
            }
        }
    }
}

/** Push setup-wizard renderer/upscale choices into emucore's
 *  EmuConfig before runVMThread. ApplySettings inside Initialize
 *  picks them up; if a VM is already up, the JNI helpers also
 *  call MTGS::ApplySettings inline.
 *
 *  Also resolves and applies the per-game / global Settings from
 *  ConfigStore (MTVU and friends) — currentGame.serial picks the
 *  right override tier; null falls back to global. Resolution
 *  order: per-game JSON overlay → global → hardcoded defaults. */
/** Number of distinct physical gamepads/joysticks connected right now
 *  (excludes virtual devices). Drives the boot-time PS2-port-2 enable for
 *  local co-op — 2+ pads → connect Player 2's controller at VM init. */
private fun connectedGamepadCount(): Int {
    var n = 0
    var sawJoyCon = false
    for (id in InputDevice.getDeviceIds()) {
        val dev = InputDevice.getDevice(id) ?: continue
        if (dev.isVirtual) continue
        val s = dev.sources
        val isPad = (s and InputDevice.SOURCE_GAMEPAD) == InputDevice.SOURCE_GAMEPAD ||
            (s and InputDevice.SOURCE_JOYSTICK) == InputDevice.SOURCE_JOYSTICK
        if (!isPad) continue
        // Nintendo Joy-Cons (vendor 0x057E) enumerate as two InputDevices per pair
        // but are combined onto ONE PS2 port (see PadRouter.portForDevice), so count
        // ALL Nintendo pads as a SINGLE logical controller — a lone pair must not
        // auto-enable PS2 port 2. Every other vendor is still counted per device.
        if (dev.vendorId == 0x057E) { sawJoyCon = true; continue }
        n++
    }
    return n + (if (sawJoyCon) 1 else 0)
}

fun applyRendererPrefs() {
    // Resolve per-game (∘ global) settings up front so the renderer backend
    // and internal resolution come from THIS title's tier, not a stale
    // global value. Sync the session state the Renderer UI reads, too.
    // Resolve via settingsKey (serial for discs, filename stem for
    // serial-less ELF/homebrew) so ELF per-game settings survive a reboot
    // instead of falling back to global (issue #253).
    var resolved = com.xeno.config.ConfigStore.resolveForGame(
        com.xeno.config.ConfigStore.effectiveKey(currentGame.value?.settingsKey))
    // Build immutable input maps before the VM starts so the first ABXY
    // edge never pays SharedPreferences parsing on the UI thread.
    ControllerMappings.warmRuntimeCaches()
    // Per-game memory cards (NetherSX2-style): when the global toggle is
    // on, point Slot 1 at a serial-named card (the core auto-creates +
    // formats it at boot) — but ONLY for games still on the factory-default
    // card. A user who assigned a real card (imported/created, globally OR
    // per-game) has a non-default filename, so we must NOT clobber it with a
    // blank serial card. (Bug: the old guard compared against the current
    // global, which a global assignment always equals, so it wiped it.)
    currentGame.value?.serial?.takeIf { it.isNotBlank() }?.let { serial ->
        if (prefs.getBoolean("memcard.perGame", false) &&
            resolved.memoryCardSlot1Filename.equals("mcd001.ps2", ignoreCase = true)) {
            resolved = resolved.copy(
                memoryCardSlot1Filename = "$serial.ps2",
                memoryCardSlot1Enabled = true,
            )
        }
    }
    // Per-game BIOS: boot with the game's chosen BIOS if it set one, else fall
    // back to the global BIOS — so a previous game's per-game pick never sticks.
    // The file is in the same app-private BIOS dir as the global one, so only the
    // Filenames/BIOS *filename* changes; commit before the VM's LoadBIOS runs.
    run {
        val effectiveBios = resolved.biosFilename.takeIf { it.isNotBlank() }
            ?: bios.value?.takeIf { it.isNotEmpty() }?.let { File(it).name }
        if (!effectiveBios.isNullOrBlank()) {
            NativeApp.setSetting("Filenames", "BIOS", "string", effectiveBios)
            NativeApp.commitSettings()
        }
    }
    upscale.value = resolved.upscaleFloat
    renderer.value = resolved.renderer

    // GPU turbo, resolved per game like the driver below it. Applied here rather than
    // through the config tree because it is not an emulator setting at all -- it is a KGSL
    // ioctl straight to the Adreno kernel driver, so nothing in g_cfg would carry it.
    //
    // Safe unconditionally: adrenotools no-ops on non-Adreno hardware and if /dev/kgsl-3d0
    // cannot be opened. Re-applied on every start so turning it off actually releases the
    // clocks on the next boot rather than persisting until reboot.
    runCatching { net.rpcsx.RPCSX.instance.setGpuTurbo(resolved.ps3.gpuTurbo) }

    NativeApp.renderUpscalemultiplier(upscale.value)
    // Pin custom Vulkan driver (if any) BEFORE the renderer write —
    // the renderer JNI may trigger MTGS::ApplySettings which can
    // re-open the GS device and run Vulkan::LoadVulkanLibrary. The
    // VK loader reads the pinned path lazily so the order matters.
    val ctx = instance?.applicationContext
    // Per-game GPU driver: pin THIS title's resolved driver (blank = system). Keep the
    // session mirror in sync so the picker UI + delete/reselect logic stay correct.
    val pickedId = resolved.customDriverId.takeIf { it.isNotBlank() }
    customDriverId.value = pickedId
    val picked: com.xeno.CustomDriver.InstalledDriver? =
        if (ctx != null) pickedId?.let { id ->
            com.xeno.CustomDriver.listInstalled(ctx).firstOrNull { it.id == id }
        } else null
    if (ctx != null) com.xeno.CustomDriver.applyToNative(ctx, picked)
    when (renderer.value) {
        "vulkan" -> NativeApp.renderVulkan()
        "opengl" -> NativeApp.renderOpenGL()
        "software" -> NativeApp.renderSoftware()
        else -> NativeApp.renderAuto()
    }
    resolved.applyTo()
    // applyTo() pushed the per-stat OSD flags (= "Custom"); re-assert the stored OSD
    // mode on top so a Full / Min / Off choice from the menu or hotkey survives a
    // relaunch instead of snapping back to the per-stat selection every boot.
    InGameOverlay.applyStoredOsdMode()
    // Per-game screen orientation: apply THIS title's rotation now that currentGame is
    // set. requestedOrientation is an Activity property → hop to the UI thread (we're on
    // the VM launch thread here). Reverts to global on exit-to-library (see stop()).
    instance?.runOnUiThread { instance?.applyEmulationOrientation() }
    // #254: cache whether this title runs with the emulated USB keyboard so
    // dispatchKeyEvent can forward physical-keyboard keys to it. applyTo()
    // already pushed [USB1] Type + the live attach (usbSetKeyboardEnabled).
    usbKeyboardActive = resolved.usbKeyboard

    // A PS2 pad block used to sit here: Pad1/Pad2 Deadzone, Pad2 Type =
    // DualShock2 when a second controller was present, and the multitap
    // arming (MultitapPort1/2 plus Pad3..Pad8). All of it configured PCSX2's
    // pad plugin -- RPCS3 has none of those keys, so every call landed in
    // Unsupported.note() and did nothing.
    //
    // Nothing replaces it. RPCS3 opens all seven pad ports itself, so there
    // is no per-port enable to arm before boot and no accessory to switch on;
    // connecting a controller is all it takes. Stick shaping stays app-side
    // (ControllerMappings.stickDeadzone, re-normalized in shapeStickMag).

    // Settings.applyTo() above writes the persisted FrameLimitEnable
    // into the BASE settings layer; override it here with the
    // in-session overlay toggle so the user's runtime choice sticks
    // across game launches within one app run. Both writes are
    // needed: native-lib's runVMThread re-reads FrameLimitEnable
    // from the BASE layer right after VMManager::Initialize and
    // calls SetLimiterMode based on that, so a bare
    // speedhackLimitermode() here gets clobbered by VM init.
    // Mode 0 = Nominal (60fps cap), 3 = Unlimited.
    val limit = InGameOverlay.frameLimitOn.value
    NativeApp.setSetting("EmuCore/GS", "FrameLimitEnable", "bool", limit.toString())
    // Preserve an active fast-forward / slow-down latch across a settings apply.
    // Otherwise this re-application of the limiter clobbers mode 1/2 back to the base
    // limit while the toggle state stays ON — so fast-forward is "forgotten" and the
    // user has to toggle off then on again to resync. Re-assert the latched mode.
    NativeApp.speedhackLimitermode(
        when {
            fastForwardToggleActive -> ffLimiterMode()
            slowDownToggleActive -> 2
            else -> if (limit) 0 else 3
        }
    )
}

/**
 * Set the active game path/URI and restart the VM. Used by
 * Library card taps — the URI comes from the user's persisted
 * ROMs tree (already has read perm) so emucore's FileSystem
 * routines can open it via the content:// JNI bridge.
 *
 * `info` is the GameInfo from the library scan when available;
 * stored on MainActivityRuntime.currentGame so the in-game overlay can show
 * cover art / extension badge / pre-resolved compat stars
 * without re-querying gamedb. Pass null when launching from a
 * path that doesn't have a GameInfo (Swap/Boot Disc file picker).
 */
fun launchGame(uri: String, info: GameInfo? = null, external: Boolean = false) {
    if (uri.isBlank()) {
        println("@@ANDROID_LAUNCH_REJECT@@ reason=blank_uri title=${info?.title ?: ""}")
        return
    }
    // A licence-locked title cannot boot — BootGame fails with DecryptionError — so ask
    // for the key instead of spending a whole VM start-up to say so. The library catches
    // this a level earlier (HomeViewModel.launch, before markPlayed); this is what covers
    // the paths that bypass the ViewModel, the settings screen's Play action above all.
    //
    // Only titles carrying a scanned GameInfo are caught: externalGameInfo() builds a
    // fresh one for intents and shortcuts, where locked defaults to false, and those
    // still fall through to the boot-failure toast.
    if (info?.locked == true) {
        println("@@ANDROID_LAUNCH_REJECT@@ reason=locked title=${info.title}")
        com.xeno.LicencePrompt.ask(info)
        return
    }
    // Remember the game for a post-exit re-launch from the Save Manager (#374).
    if (info != null) contextGame.value = info
    println(
        "@@ANDROID_LAUNCH_GAME@@ title=${info?.title ?: "<direct>"} " +
            "uri=${com.xeno.CloudSync.redactUrl(uri.take(240))} state=${eState.value} runLoop=$vmRunLoopActive " +
            "stopping=$vmStopInProgress nativeReady=${nativeReady.value}"
    )
    // Refresh the ANGLE EGL env before the GS thread opens the GL context, so a
    // just-changed AndroidUseAngleOpenGL / renderer choice takes effect on this boot.
    instance?.applicationContext?.let { applyAngleEnv(it) }
    // Native GS/settings calls in start()→applyRendererPrefs null-deref if the
    // base settings layer isn't installed yet (initialize() not finished). On a
    // cold first launch — reliably on Samsung DeX — a fast game tap races init
    // and crashes with no error. Defer until nativeReady; the LaunchedEffect
    // watching pendingLaunch fires it once init completes.
    if (!nativeReady.value) {
        println("@@ANDROID_LAUNCH_DEFER@@ nativeReady=false — queuing '${info?.title ?: com.xeno.CloudSync.redactUrl(uri.take(80))}'")
        pendingLaunch.value = uri to info
        return
    }
    currentGame.value = info
    launchedExternally = external
    m_szGamefile = uri
    synchronized(vmLifecycleLock) {
        if (eState.value != EmuState.STOPPED || vmStopInProgress || vmRunLoopActive) {
            vmRestartAfterStop = true
        }
    }
    if (eState.value == EmuState.STOPPED && !vmStopInProgress && !vmRunLoopActive)
        start()
    else
        stop(restartAfterStop = true)
}

private fun launchPendingExternalGameIfReady() {
    if (!setupComplete.value || !nativeReady.value) return
    // A deferred library launch (nativeReady-gated) fires first, keeping its
    // GameInfo so per-game settings / title still apply.
    pendingLaunch.value?.let { (u, i) ->
        pendingLaunch.value = null
        launchGame(u, i)
        return
    }
    val queued = pendingExternalLaunch.value
    if (queued.isNullOrEmpty()) return
    pendingExternalLaunch.value = null
    // Launching from a frontend (Cocoon/Daijisho/ES-DE) used to pass a null GameInfo,
    // so settingsKey was null and launchGame resolved GLOBAL settings — per-game
    // settings, per-game memory cards and per-game orientation all silently ignored,
    // while the same title launched from our own library applied them correctly.
    // Build a GameInfo for the incoming URI so the external path keys off the same
    // settingsKey the library path does (serial for discs, filename stem otherwise).
    launchGame(queued, externalGameInfo(queued), external = true)
}

/**
 * Minimal [GameInfo] for a URI arriving from outside the app. The serial is probed
 * off the image the same way the library scan does (SYSTEM.CNF via
 * NativeApp.getGameSerialFromFd) so per-game settings stored under the serial are
 * found. A failed probe is fine and expected for ELF/homebrew — settingsKey then
 * falls back to the filename stem, matching issue #253's behaviour.
 */
private fun externalGameInfo(uriString: String): GameInfo? = runCatching {
    val uri = uriString.toUri()
    val name = uri.lastPathSegment?.substringAfterLast('/')?.substringAfterLast(':').orEmpty()
    val stem = name.substringBeforeLast('.').ifBlank { name }
    val serial = runCatching {
        val ctx = instance ?: return@runCatching null
        // detachFd() hands ownership of the fd to native, which closes it — same
        // contract GameLibraryRepository.probeDocument/probeRaw use. Do NOT wrap in
        // use{}: closing an already-detached descriptor is not ours to do.
        val raw = if (uri.scheme == "content") {
            val pfd = ctx.contentResolver.openFileDescriptor(uri, "r") ?: return@runCatching null
            NativeApp.getGameSerialFromFd(pfd.detachFd())
        } else {
            val f = java.io.File(uri.path ?: return@runCatching null)
            if (!f.isFile) return@runCatching null
            val pfd = ParcelFileDescriptor.open(f, ParcelFileDescriptor.MODE_READ_ONLY)
            NativeApp.getGameSerialFromFd(pfd.detachFd())
        }
        // The probe tags its result "<platform>:<serial>" when SYSTEM.CNF parsed.
        raw?.takeIf { it.isNotBlank() }?.substringAfterLast(':')?.takeIf { it.isNotBlank() }
    }.getOrNull()
    GameInfo(
        uri = uri,
        title = stem,
        serial = serial,
        extension = name.substringAfterLast('.', "").uppercase(),
    )
}.getOrNull()

package com.xeno;

import android.content.Context;
import android.view.Surface;

import com.xeno.BiosInfo;

/**
 * XENO's native seam.
 *
 * WHY THIS EXISTS
 * XENO's UI reached native through NativeApp in the kr.co.iefriends.pcsx2
 * package - 134 native methods belonging to a THIRD-PARTY rights holder, and
 * bound to PCSX2 besides. We do not copy that. This class re-declares the same
 * functional surface and implements it against RPCS3 instead, so the XENO UI
 * runs unchanged apart from its import line and nothing third-party crosses over.
 *
 * THREE KINDS OF METHOD LIVE HERE, and the distinction matters:
 *
 *   [MAPPED]      Backed by a real RPCS3 entry point. Works.
 *
 *   [PS3-N/A]     The concept does not exist on PS3 (PS2 memory cards, PNACH
 *                 patches, GUNCON lightguns, EE/VU speedhacks, RetroAchievements
 *                 - which has no PS3 support at all). These return a neutral
 *                 value AND the screen that drives them must be removed. A
 *                 control that silently does nothing is worse than an absent one.
 *
 *   [TODO]        Real PS3 analogue exists in RPCS3 but is not wired yet.
 *                 Distinguished from PS3-N/A on purpose: these are work items,
 *                 not dead ends.
 *
 * Every unimplemented method logs once via Unsupported.note() so a screen that
 * looks alive but is not shows up in logcat rather than being discovered by a
 * user.
 */
public final class NativeApp {

    private NativeApp() {}

    // ---------------------------------------------------------------
    // Low-level binding to the RPCS3 core.
    // The core is dlopen()ed and its _rpcsx_* entry points resolved by
    // the JNI bridge; see Rpcs3Bridge.
    // ---------------------------------------------------------------

    // ===== Lifecycle =====

    /** [MAPPED] */
    public static void initializeOnce(Context context) {
        Rpcs3Bridge.initializeOnce(context);
    }

    /** [MAPPED] -> _rpcsx_initialize */
    public static void initialize(String path, String biosFolder, int apiVer) {
        // biosFolder is a PS2 concept; PS3 firmware lives in dev_flash under the
        // root dir and is installed, not pointed at. apiVer is unused by RPCS3.
        Rpcs3Bridge.initialize(path);
    }

    /** [MAPPED] -> _rpcsx_boot */
    public static boolean runVMThread(String path) {
        return Rpcs3Bridge.boot(path);
    }

    /** [MAPPED] -> _rpcsx_getState */
    public static boolean hasActiveVM() {
        return Rpcs3Bridge.hasActiveVm();
    }

    /** [MAPPED] -> _rpcsx_pause */
    public static void pause() { Rpcs3Bridge.pause(); }

    /** [MAPPED] -> _rpcsx_resume */
    public static void resume() { Rpcs3Bridge.resume(); }

    /** [MAPPED] -> _rpcsx_kill */
    public static void shutdown() { Rpcs3Bridge.shutdown(); }

    /** [MAPPED] */
    public static void vmSetPaused(boolean paused) {
        if (paused) pause(); else resume();
    }

    // ===== Surface =====

    /** [MAPPED] -> _rpcsx_surfaceEvent */
    public static void onNativeSurfaceCreated() { Rpcs3Bridge.surfaceCreated(); }

    /** [MAPPED] -> _rpcsx_surfaceEvent */
    public static void onNativeSurfaceChanged(Surface surface, int w, int h) {
        Rpcs3Bridge.surfaceChanged(surface, w, h);
    }

    /** [MAPPED] -> _rpcsx_surfaceEvent */
    public static void onNativeSurfaceDestroyed() { Rpcs3Bridge.surfaceDestroyed(); }

    // ===== Settings =====

    /**
     * [MAPPED] -> _rpcsx_settingsSet
     *
     * XENO addresses settings as (section, key, type, value) against a PCSX2
     * INI. RPCS3's tree is addressed by a "@@"-joined path and takes a
     * JSON-encoded value, so we translate. The `type` argument tells us how to
     * encode: strings and enums must be quoted, numbers and bools must not.
     */
    public static void setSetting(String section, String key, String type, String value) {
        Rpcs3Bridge.setSetting(section, key, type, value);
    }

    /** [MAPPED] */
    public static void commitSettings() { Rpcs3Bridge.commitSettings(); }

    // ===== Save states =====

    /** [MAPPED] RPCS3 has savestates; slots map to its own save files. */
    public static boolean saveStateToSlot(int slot) { return Rpcs3Bridge.saveState(slot); }

    /** [MAPPED] */
    public static boolean loadStateFromSlot(int slot) { return Rpcs3Bridge.loadState(slot); }

    /** [MAPPED] Slot preview, captured by the core at save time. Null if the slot has none. */
    public static byte[] getImageSlot(int slot) { return Rpcs3Bridge.thumbnailForSlot(slot); }

    /** [TODO] */
    public static byte[] getSaveStateImage(String path) { Unsupported.note("getSaveStateImage"); return null; }

    /** [MAPPED] Occupancy for the save slot picker. Non-empty means the slot holds a state. */
    public static String getGamePathSlot(int slot) { return Rpcs3Bridge.gamePathForSlot(slot); }

    /** [TODO] Autosave is an XENO feature layered on PCSX2 savestates. */
    /** [MAPPED] Auto-save state, kept in a reserved slot above the ten the picker shows. */
    public static boolean hasAutosaveState() { return Rpcs3Bridge.hasAutosaveState(); }
    public static boolean saveAutosaveState() { return Rpcs3Bridge.saveAutosaveState(); }
    public static boolean loadAutosaveState() { return Rpcs3Bridge.loadAutosaveState(); }

    /** [MAPPED] Where a slot's state file lives. Not getGamePathSlot, which answers a title id. */
    public static String getSlotFilePath(int slot) { return Rpcs3Bridge.slotFilePath(slot); }

    /** [MAPPED] Whether a slot holds a state. Ask this rather than probing a path. */
    public static boolean hasStateInSlot(int slot) { return Rpcs3Bridge.hasState(slot); }

    /** [MAPPED] Delete a slot's state and thumbnail. The core resolves the real filename. */
